"""Pure RFQ arithmetic; never discovers records or substitutes unknown inputs."""
from __future__ import annotations

from collections import defaultdict
from decimal import Decimal, ROUND_FLOOR, ROUND_HALF_UP, localcontext

from .models import BidInput, Material

CENT = Decimal("0.01")
ZERO = Decimal(0)


def cents(value: Decimal) -> Decimal:
    return value.quantize(CENT, rounding=ROUND_HALF_UP)


def allocate_cents(total: Decimal, weights: dict[str, Decimal]) -> dict[str, Decimal]:
    """Conserve rounded total, largest remainders first; ties by position string."""
    if not total.is_finite() or total < 0 or not weights or any(
        not w.is_finite() or w < 0 for w in weights.values()
    ):
        raise ValueError("Allocation requires finite nonnegative amount and weights")
    total = cents(total)
    weight = sum(weights.values(), ZERO)
    if not weight:
        if total:
            raise ValueError("Cannot allocate a nonzero fee against zero weights")
        return dict.fromkeys(weights, ZERO)
    with localcontext() as ctx:
        ctx.prec = 60
        exact = {key: total * 100 * value / weight for key, value in weights.items()}
        whole = {key: int(value.to_integral_value(rounding=ROUND_FLOOR)) for key, value in exact.items()}
        remainder = int(total * 100) - sum(whole.values())
        order = sorted(weights, key=lambda key: (-(exact[key] - whole[key]), key))
        for key in order[:remainder]:
            whole[key] += 1
        return {key: Decimal(value) / 100 for key, value in whole.items()}


def select_material(position) -> Material | None:
    if not position.catalogue_complete:
        raise ValueError(f"Unresolved catalogue search for {position.position}")
    matches = [m for m in position.candidates if m.active and m.attributes == position.requirement]
    if len(matches) > 1:
        raise ValueError(f"Ambiguous material for {position.position}")
    return matches[0] if matches else None


def calculate_bid(data: BidInput | dict) -> dict:
    """Return answer plus audit trace. Decimal outputs remain exact until wire serialization."""
    data = data if isinstance(data, BidInput) else BidInput.model_validate(data)
    with localcontext() as context:
        context.prec = 60
        return _calculate(data)


def _calculate(data: BidInput) -> dict:
    selected = {p.position: select_material(p) for p in data.positions}
    answer = dict(tender_reference=data.tender_reference, decision="bid", currency="EUR",
                  discount_percent=data.discount.percent, positions=[], total_net=ZERO)
    missing = [key for key, value in selected.items() if value is None]
    if missing:
        answer.update(decision="no_bid", discount_percent=(ZERO if data.discount.minimum_goods_eur is not None
                                                          else data.discount.percent))
        return {"answer": answer, "audit": {"missing_material_positions": missing}}

    demand = defaultdict(int)
    catalogue = {}
    base, goods, trace = {}, {}, {}
    for p in data.positions:
        m = selected[p.position]
        if m.number in catalogue and catalogue[m.number] != m:
            raise ValueError(f"Conflicting ERP facts for material {m.number}")
        catalogue[m.number] = m
        demand[m.number] += p.quantity
        conditions = [c for c in m.conditions if c.valid_from <= data.scenario_date <= c.valid_until]
        if len(conditions) != 1:
            raise ValueError(f"Expected one valid price condition for {p.position}")
        condition = conditions[0]
        scales = [s for s in condition.scales if s.minimum_pieces <= p.quantity]
        if not scales:
            raise ValueError(f"No applicable price scale for {p.position}")
        scale = max(scales, key=lambda s: s.minimum_pieces)
        base[p.position] = cents(scale.price / condition.price_unit_pieces * condition.eur_per_currency)
        goods[p.position] = base[p.position] * p.quantity
        trace[p.position] = {"scale_minimum": scale.minimum_pieces, "goods_eur": goods[p.position]}

    goods_total = cents(sum(goods.values(), ZERO))
    discount = data.discount.percent
    if data.discount.minimum_goods_eur is not None and goods_total < data.discount.minimum_goods_eur:
        discount = ZERO
    answer["discount_percent"] = discount
    factor = 1 - discount / 100
    setup = dict.fromkeys(selected, ZERO)
    pool_audit = {}
    for pool in data.setup_pools:
        weights = {p.position: Decimal(p.quantity) * selected[p.position].allocation_mass_kg
                   for p in data.positions if p.position in pool.positions}
        allocations = allocate_cents(pool.fee_eur, weights)
        pool_audit[pool.key] = allocations
        for key, value in allocations.items():
            setup[key] += value

    rebates = dict.fromkeys(selected, ZERO)
    bonus_total = ZERO
    if data.bonus:
        eligible = {key: goods[key] for key in data.bonus.positions}
        eligible_total = sum(eligible.values(), ZERO)
        lower = ZERO
        raw_bonus = ZERO
        for band in data.bonus.bands:
            upper = eligible_total if band.up_to_eur is None else min(eligible_total, band.up_to_eur)
            raw_bonus += max(ZERO, upper - lower) * band.percent / 100
            if band.up_to_eur is None or band.up_to_eur >= eligible_total:
                break
            lower = band.up_to_eur
        else:
            if eligible_total > lower:
                raise ValueError("Bonus bands do not cover eligible goods total")
        bonus_total = cents(raw_bonus)
        rebates.update(allocate_cents(bonus_total, eligible))

    for p in data.positions:
        key, m = p.position, selected[p.position]
        mass = m.surcharge_mass_kg * p.metal_eur_per_kg
        cartons = (p.quantity + m.carton_pieces - 1) // m.carton_pieces
        packaging = cartons * p.carton_eur
        setup_total = p.ordinary_setup_eur + setup[key]
        unit = base[key] * (factor if p.discount_scope != "none" else 1)
        unit += mass * (factor if p.discount_scope == "base_and_mass" else 1)
        unit += (setup_total + packaging - rebates[key]) / p.quantity
        if unit < 0:
            raise ValueError(f"Negative final unit price for {key}")
        weeks = m.stock_weeks if m.stock_pieces >= demand[m.number] else m.production_weeks
        committed = bool(p.commitment and p.commitment.material_number == m.number
                         and demand[m.number] <= p.commitment.ceiling_pieces)
        if committed:
            weeks = p.commitment.weeks
        # Surcharge reports mass plus per-piece setup, before any discount (rule 25).
        row = dict(position=key, material_number=m.number, quantity=p.quantity,
                   base_unit_price=base[key], surcharge_per_unit=cents(mass + setup_total / p.quantity),
                   packaging_per_unit=cents(packaging / p.quantity), rebate_total=rebates[key],
                   unit_price=cents(unit), lead_time_weeks=weeks)
        answer["positions"].append(row)
        trace[key].update(pooled_demand=demand[m.number], cartons=cartons, mass_eur_per_piece=mass,
                          setup_eur=setup_total, packaging_eur=packaging, commitment_applied=committed,
                          unrounded_unit_price=unit)
    answer["total_net"] = cents(sum((r["quantity"] * r["unit_price"] for r in answer["positions"]), ZERO))
    return {"answer": answer, "audit": {"goods_total_eur": goods_total, "bonus_total_eur": bonus_total,
                                       "setup_allocations": pool_audit, "positions": trace}}

"""Run-local observations and citations. No credentials or page content in stdout logs."""
from __future__ import annotations

import hashlib
from datetime import datetime, timezone


class EvidenceBook:
    def __init__(self):
        self.observations: dict[str, dict] = {}
        self.facts: dict[str, dict] = {}

    def observe(self, url: str, text: str) -> str:
        key = f"obs-{len(self.observations) + 1}"
        self.observations[key] = {"url": url, "text": text,
                                  "sha256": hashlib.sha256(text.encode()).hexdigest(),
                                  "observed_at": datetime.now(timezone.utc).isoformat()}
        return key

    def cite(self, observation_id: str, quote: str, meaning: str) -> str:
        observation = self.observations[observation_id]
        if not quote.strip() or quote not in observation["text"]:
            raise ValueError("Citation must be an exact nonempty substring of the observation")
        key = f"ev-{len(self.facts) + 1}"
        self.facts[key] = {"observation_id": observation_id, "quote": quote, "meaning": meaning}
        return key

    def validate_references(self, value):
        if isinstance(value, dict):
            for key, child in value.items():
                if key == "evidence_ids":
                    if not child or any(ref not in self.facts for ref in child):
                        raise ValueError("Unknown or empty evidence references")
                else:
                    self.validate_references(child)
        elif isinstance(value, list):
            for child in value:
                self.validate_references(child)

    def dump(self):
        return {"observations": self.observations, "facts": self.facts}

"""Helpers for records the model has selected and normalized; no network access."""
from __future__ import annotations

from datetime import date, datetime, timezone
from decimal import Decimal

from .models import Attributes


def timestamp(value: str) -> datetime:
    """Date-only records sort at UTC midnight; timestamps must include an offset."""
    if len(value) == 10:
        return datetime.combine(date.fromisoformat(value), datetime.min.time(), timezone.utc)
    result = datetime.fromisoformat(value.replace("Z", "+00:00"))
    if result.tzinfo is None:
        raise ValueError("Record timestamps must include a timezone")
    return result.astimezone(timezone.utc)


def latest(records: list[dict]) -> dict | None:
    if not records:
        return None
    newest = max(timestamp(r["dated"]) for r in records)
    chosen = [r for r in records if timestamp(r["dated"]) == newest]
    if len(chosen) != 1:
        raise ValueError("Ambiguous records with the same latest timestamp")
    return chosen[0]


def authorized_record(records: list[dict], reference: str, sender: str, topic: str,
                      scenario_date: str, key: str | None = None) -> dict | None:
    """Exact reference/topic/key, case-insensitive full sender, no future records.

    The caller derives the authorized full sender from the brief and bidder domain.
    Latest selection happens BEFORE evaluating quantity or value conditions.
    """
    cutoff = date.fromisoformat(scenario_date)
    return latest([r for r in records if r["reference"] == reference
                   and r["sender"].casefold() == sender.casefold() and r["topic"] == topic
                   and (key is None or r.get("key") == key)
                   and timestamp(r["dated"]).date() <= cutoff])


def final_quantity(original: int, unit: str, pieces_per_set: int, position: str,
                   answers: list[dict], scenario_date: str) -> int:
    """Withdrawals remove referenced changes; newest remaining quantity change wins."""
    if type(original) is not int or original <= 0 or type(pieces_per_set) is not int or pieces_per_set <= 0:
        raise ValueError("Quantities and set factors must be positive integers")
    valid = [r for r in answers if timestamp(r["dated"]).date() <= date.fromisoformat(scenario_date)]
    ids = [r["number"] for r in valid]
    if len(set(ids)) != len(ids):
        raise ValueError("Duplicate Q&A answer numbers")
    indexed = {r["number"]: r for r in valid}
    withdrawn = set()
    for row in valid:
        for number in row.get("withdraws", []):
            if number not in indexed or timestamp(indexed[number]["dated"]) >= timestamp(row["dated"]):
                raise ValueError("Withdrawal must name an earlier observed answer")
            if indexed[number].get("withdraws"):
                raise ValueError("Withdrawal of a withdrawal requires manual rule interpretation")
            withdrawn.add(number)
    change = latest([r for r in valid if r["number"] not in withdrawn
                     and r.get("position") == position and "quantity" in r])
    quantity = original if change is None else change["quantity"]
    if type(quantity) is not int or quantity <= 0:
        raise ValueError("Final quantity must be a positive integer")
    if unit not in {"Stück", "Satz"}:
        raise ValueError("Normalize the observed unit to Stück or Satz")
    return quantity * (pieces_per_set if unit == "Satz" else 1)


def amended_requirement(attributes: dict, revision: str, requirement: str, amendments: list[dict],
                        scenario_date: str, usable_stroke: bool, reserve_per_end_mm: str | None) -> dict:
    """Apply amendments per attribute only to the governing revision, then derive stroke."""
    output = Attributes.model_validate(attributes).model_dump()
    applicable = [r for r in amendments if r["revision"] == revision and r["requirement"] == requirement
                  and timestamp(r["dated"]).date() <= date.fromisoformat(scenario_date)]
    for row in applicable:
        if not set(row["changes"]) <= set(output):
            raise ValueError("Unknown amended attribute")
    for key in output:
        row = latest([r for r in applicable if key in r["changes"]])
        if row:
            output[key] = row["changes"][key]
    if usable_stroke:
        if reserve_per_end_mm is None:
            raise ValueError("Usable stroke requires revision-specific technical reserve")
        reserve = Decimal(reserve_per_end_mm)
        if not reserve.is_finite() or reserve < 0:
            raise ValueError("Invalid per-end reserve")
        output["stroke_mm"] = Decimal(str(output["stroke_mm"])) + 2 * reserve
    return Attributes.model_validate(output).model_dump(mode="json")


def window_rate(windows: list[dict], scenario_date: str) -> str:
    day = date.fromisoformat(scenario_date)
    selected = [r for r in windows if date.fromisoformat(r["valid_from"]) <= day
                <= date.fromisoformat(r["valid_until"])]
    if len(selected) != 1:
        raise ValueError("Expected exactly one applicable index validity window")
    value = Decimal(str(selected[0]["rate"]))
    if not value.is_finite() or value < 0:
        raise ValueError("Invalid index rate")
    return str(value)


RESOLVERS = {"authorized_record": authorized_record, "final_quantity": final_quantity,
             "amended_requirement": amended_requirement, "window_rate": window_rate}

"""Bounded browser actions selected by the model; connects only to supplied CDP browsers."""
from __future__ import annotations

import base64
import io
import zipfile
from pathlib import Path
from urllib.parse import urlsplit

from .evidence import EvidenceBook

MAX_DOCUMENT = 20 * 1024 * 1024


def origin(url: str) -> str:
    parts = urlsplit(url)
    if parts.scheme not in {"http", "https"} or not parts.hostname or parts.username or parts.password:
        raise ValueError("Expected an HTTP(S) URL without embedded credentials")
    return f"{parts.scheme}://{parts.netloc.lower()}"


def document_text(payload: bytes, name: str, member: str | None = None) -> str:
    """Read one selected document; ZIP members are listed until the model selects one."""
    if len(payload) > MAX_DOCUMENT:
        raise ValueError("Document exceeds 20 MiB")
    if name.lower().endswith(".zip"):
        with zipfile.ZipFile(io.BytesIO(payload)) as archive:
            if member is None:
                return "ZIP members (select one with member):\n" + "\n".join(archive.namelist()[:500])
            info = archive.getinfo(member)
            if info.is_dir() or info.file_size > MAX_DOCUMENT or member.lower().endswith(".zip"):
                raise ValueError("Unsupported or oversized ZIP member")
            # Never extract to the filesystem; path traversal names are harmless here.
            return document_text(archive.read(info), member)
    if name.lower().endswith(".pdf") or payload.startswith(b"%PDF"):
        import pymupdf
        with pymupdf.open(stream=payload, filetype="pdf") as document:
            return "\n".join(f"[page {i + 1}]\n{page.get_text()}" for i, page in enumerate(document))
    if name.lower().endswith((".txt", ".csv", ".md", ".json", ".xml", ".html")):
        return payload.decode("utf-8-sig")
    raise ValueError("Unsupported document format; use browser rendering for this document")


class BrowserSession:
    def __init__(self, browsers, book: EvidenceBook, allowed_urls: list[str]):
        self.browsers, self.book = browsers, book
        self.origins = {origin(url) for url in allowed_urls}
        self.pages = []
        self.controls = {}
        self.observed_pages = {}
        self.generation = 0
        self.downloads = {}

    @classmethod
    async def connect(cls, playwright, endpoints: list[str], book: EvidenceBook, allowed_urls: list[str]):
        if not 1 <= len(endpoints) <= 4:
            raise ValueError("Supply between one and four existing CDP browsers")
        browsers = []
        for endpoint in endpoints:
            parsed = urlsplit(endpoint)
            if parsed.hostname not in {"localhost", "127.0.0.1", "::1"}:
                raise ValueError("CDP endpoints must be local")
            browsers.append(await playwright.chromium.connect_over_cdp(endpoint, timeout=15000))
        session = cls(browsers, book, allowed_urls)
        for browser in browsers:
            for context in browser.contexts:
                context.set_default_timeout(8000)
                context.set_default_navigation_timeout(15000)
                await context.route("**/*", session._route)
        return session

    async def _route(self, route):
        url = route.request.url
        try:
            allowed = origin(url) in self.origins
        except ValueError:
            allowed = url.startswith(("data:", "blob:", "about:"))
        await (route.continue_() if allowed else route.abort())

    def page_list(self):
        for browser in self.browsers:
            for context in browser.contexts:
                for page in context.pages:
                    if page not in self.pages:
                        self.pages.append(page)
        return [{"page": i, "url": p.url} for i, p in enumerate(self.pages) if not p.is_closed()]

    def page(self, index):
        self.page_list()
        if type(index) is not int or index < 0 or index >= len(self.pages) or self.pages[index].is_closed():
            raise ValueError("Unknown or closed page")
        return self.pages[index]

    async def observe(self, page_index: int, frame_index=0, offset=0, control_offset=0):
        page = self.page(page_index)
        if min(frame_index, offset, control_offset) < 0 or frame_index >= len(page.frames):
            raise ValueError("Invalid observation offset or frame")
        frame = page.frames[frame_index]
        text = await frame.locator("body").inner_text(timeout=8000)
        self.generation += 1
        self.controls.clear()
        controls = []
        locator = frame.locator("a, button, input, textarea, select, [role=button], [role=tab], [role=checkbox]")
        total = await locator.count()
        for index in range(control_offset, min(total, control_offset + 100)):
            item = locator.nth(index)
            if not await item.is_visible():
                continue
            handle = await item.element_handle()
            info = await handle.evaluate("""e => ({tag: e.tagName, type: e.getAttribute('type'),
                text: (e.innerText || e.textContent || '').slice(0, 500),
                label: e.getAttribute('aria-label') || (e.labels ? [...e.labels].map(x => x.innerText).join(' ') : ''),
                placeholder: e.getAttribute('placeholder'), name: e.getAttribute('name'),
                href: e.getAttribute('href'), options: e.tagName === 'SELECT' ?
                [...e.options].map(x => ({value: x.value, text: x.text})) : undefined})""")
            ref = f"control-{self.generation}-{index}"
            self.controls[ref] = (page_index, handle)
            controls.append({"ref": ref, **info})
        excerpt = text[offset:offset + 16000]
        observation = self.book.observe(frame.url, excerpt)
        self.observed_pages[observation] = page_index
        return {"observation_id": observation, "page": page_index, "url": frame.url, "text": excerpt,
                "text_length": len(text), "offset": offset, "controls": controls, "control_count": total,
                "frames": [{"frame": i, "url": f.url, "name": f.name} for i, f in enumerate(page.frames)],
                "pages": self.page_list()}

    async def act(self, operation: str, page: int = 0, **args):
        if operation == "pages":
            return self.page_list()
        if operation == "new_tab":
            browser_index = args.get("browser", 0)
            if type(browser_index) is not int or not 0 <= browser_index < len(self.browsers):
                raise ValueError("Unknown browser")
            new = await self.browsers[browser_index].contexts[0].new_page()
            self.page_list()
            return {"page": self.pages.index(new)}
        target = self.page(page)
        if operation == "observe":
            return await self.observe(page, args.get("frame", 0), args.get("offset", 0), args.get("control_offset", 0))
        if operation == "screenshot":
            return {"image_url": "data:image/png;base64," + base64.b64encode(await target.screenshot()).decode()}
        if operation == "read_download":
            record = self.downloads[args["download_id"]]
            text = document_text(record["bytes"], record["name"], args.get("member"))
            offset = args.get("offset", 0)
            if offset < 0:
                raise ValueError("Negative offset")
            excerpt = text[offset:offset + 24000]
            observation = self.book.observe(record["url"] + "#" + str(args.get("member", "")), excerpt)
            return {"observation_id": observation, "text": excerpt, "text_length": len(text), "offset": offset}
        try:
            if operation == "navigate":
                if origin(args["url"]) not in self.origins:
                    raise ValueError("Navigation target is outside challenge sites")
                await target.goto(args["url"], wait_until="domcontentloaded")
            elif operation == "scroll":
                await target.mouse.wheel(0, max(-800, min(800, args.get("pixels", 600))))
            elif operation in {"click", "fill", "select", "press", "download"}:
                control_page, handle = self.controls[args["ref"]]
                if control_page != page:
                    raise ValueError("Control belongs to another page")
                if operation == "click":
                    await handle.click()
                elif operation == "fill":
                    await handle.fill(args["value"])
                elif operation == "select":
                    await handle.select_option(value=args["value"])
                elif operation == "press":
                    await handle.press(args["value"])
                else:
                    async with target.expect_download(timeout=15000) as pending:
                        await handle.click()
                    download = await pending.value
                    path = await download.path()
                    if path is None or Path(path).stat().st_size > MAX_DOCUMENT:
                        raise ValueError("Missing or oversized download")
                    key = f"download-{len(self.downloads) + 1}"
                    self.downloads[key] = {"bytes": Path(path).read_bytes(), "name": download.suggested_filename,
                                           "url": download.url}
                    return {"download_id": key, "name": download.suggested_filename}
            else:
                raise ValueError("Unknown browser operation")
        finally:
            # A timed-out action may still have changed the page. Never reuse its controls.
            self.controls.clear()
        return {"status": "action_completed", "pages": self.page_list(), "next": "observe before using controls"}

