            # Keep provider's tool-call structure (and optional reasoning_content), no opaque response data.
            messages.append({k: v for k, v in message.items() if k in {
                "role", "content", "tool_calls", "reasoning_content"}})
            calls = message.get("tool_calls", [])
            images = []
            if not calls:
                messages.append({"role": "user", "content": "Continue using tools. A prose answer does not submit the bid."})
            for call in calls:
                name = call["function"]["name"]
                args = {}
                try:
                    args = json.loads(call["function"]["arguments"])
                    result = await agent.dispatch(name, args)
                    status = "ok"
                except Exception as exc:
                    # Errors are observations for the model; never infer an action failed to commit.
                    error_message = redact(str(exc), agent.log_secrets)[:1000]
                    error_key = (name, args.get("operation") if isinstance(args, dict) else None,
                                 type(exc).__name__, error_message[:160])
                    error_counts[error_key] = error_counts.get(error_key, 0) + 1
                    result = {"error": type(exc).__name__, "message": error_message,
                              "same_error_count": error_counts[error_key],
                              "next": "Re-observe; the prior action may have succeeded. Change approach after repeated errors."}
                    if error_counts[error_key] >= 3:
                        result["next"] = "Repeated failure. Stop retrying this action; inspect another control, page or frame."
                    status = "error"
                image_url = result.pop("image_url", None) if isinstance(result, dict) else None
                messages.append({"role": "tool", "tool_call_id": call["id"],
                                 "content": json.dumps(result, default=json_default, ensure_ascii=False)})
                if image_url:
                    images.append({"type": "image_url", "image_url": {"url": image_url}})
                log = {"step": step + 1, "tool": name, "status": status}
                if name == "browser" and isinstance(args, dict):
                    log["operation"] = args.get("operation")
                if status == "error":
                    log.update(error_type=result["error"], error_message=result["message"][:300],
                               same_error_count=result["same_error_count"])
                print(json.dumps(log, ensure_ascii=False), flush=True)
                if checkpoint:
                    checkpoint(agent)
                if agent.done:
                    return "prepared" if agent.prepare_only else "receipt_recorded"
            if images:
                messages.append({"role": "user", "content": images})
        raise RuntimeError("Agent step limit reached without a submission receipt")


def redact(value: str, secrets: list[str]) -> str:
    for secret in sorted(set(secrets), key=len, reverse=True):
        if secret:
            value = value.replace(secret, "[REDACTED]")
    return value


def save_artifacts(directory: Path, agent: Agent, secrets: list[str]):
    directory.mkdir(parents=True, exist_ok=True, mode=0o700)
    data = {"evidence": agent.book.dump(), "notes": agent.notes, "calculation_input": agent.calculation_input,
            "calculation": agent.calculation, "partial": agent.partial, "receipt": agent.receipt}
    path = directory / "run.json"
    temp = directory / ".run.json.tmp"
    temp.write_text(redact(json.dumps(data, default=json_default, ensure_ascii=False, indent=2), secrets))
    temp.chmod(0o600)
    temp.replace(path)


def run_seconds(run, maximum):
    """Cap the run budget using an ISO or UNIX seconds/milliseconds expiry."""
    seconds = maximum
    if run.get("expires_at") is not None:
        val = run["expires_at"]
        if isinstance(val, (int, float)):
            # The sandbox supplies milliseconds; also accept UNIX seconds.
            if val > 1e11:
                val = val / 1000.0
            expires = datetime.fromtimestamp(val, tz=timezone.utc)

